-- Opt-in sample data for the Web Admin revenue breakdown reports.
-- Run manually against a development database; this is not part of migration.sql.
-- The script is idempotent: fixture rows are updated on every run, never duplicated.
BEGIN;

VALUES ('a1000000-0000-4000-8000-000000000001','report.cashier@example.test','!','Thu ngân mẫu','0910000001',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;
SELECT 'a1000000-0000-4000-8000-000000000001', id FROM roles WHERE role_name = 'STAFF'
ON CONFLICT DO NOTHING;
VALUES ('a1000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000001','Thu ngân mẫu','0910000001','Thu ngân',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, position=EXCLUDED.position, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;

VALUES ('a1000000-0000-4000-8000-000000000021','Sản phẩm báo cáo mẫu',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET category_name=EXCLUDED.category_name, updated_at=CURRENT_TIMESTAMP;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, price=EXCLUDED.price, stock_quantity=EXCLUDED.stock_quantity, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET court_fee=EXCLUDED.court_fee, product_fee=EXCLUDED.product_fee, discount_amount=EXCLUDED.discount_amount, total_amount=EXCLUDED.total_amount, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET quantity=EXCLUDED.quantity, unit_price=EXCLUDED.unit_price, discount_amount=EXCLUDED.discount_amount, discount_percent=EXCLUDED.discount_percent;

-- ---------------------------------------------------------------------------
-- 2026 samples: more cashiers, customers, courts and products so the report has
-- a quarter-by-quarter story and the court slide can split by court.
-- ---------------------------------------------------------------------------

ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;
SELECT u.user_id, r.id FROM (VALUES
 ('b2000000-0000-4000-8000-000000000001'::uuid),
 ('b2000000-0000-4000-8000-000000000002'::uuid),
 ('b2000000-0000-4000-8000-000000000003'::uuid)) AS u(user_id)
JOIN roles r ON r.role_name = 'STAFF'
ON CONFLICT DO NOTHING;
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, position=EXCLUDED.position, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;
ON CONFLICT (id) DO UPDATE SET full_name=EXCLUDED.full_name, phone=EXCLUDED.phone, updated_at=CURRENT_TIMESTAMP;

VALUES ('b2000000-0000-4000-8000-000000000041','Dụng cụ cầu lông 2026',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET category_name=EXCLUDED.category_name, updated_at=CURRENT_TIMESTAMP;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, price=EXCLUDED.price, stock_quantity=EXCLUDED.stock_quantity, updated_at=CURRENT_TIMESTAMP;

-- Courts are created without a branch, which the court constraints allow.
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, type=EXCLUDED.type, status=EXCLUDED.status, base_price=EXCLUDED.base_price, updated_at=CURRENT_TIMESTAMP;

-- Reuse the existing 06:00-07:00 slot seeded by migration.sql; do not add demo-only slot times.
VALUES ('b2000000-0000-4000-8000-000000000061','06:00','07:00',1.0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
ON CONFLICT (id) DO UPDATE SET start_time=EXCLUDED.start_time, end_time=EXCLUDED.end_time,
    price_multiplier=EXCLUDED.price_multiplier, updated_at=CURRENT_TIMESTAMP;

-- Bookings tie paid invoices to courts so the court slide can split the court fee.
ON CONFLICT (id) DO UPDATE SET status=EXCLUDED.status, court_fee=EXCLUDED.court_fee, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET price=EXCLUDED.price;

-- Invoices for 2026: court fee, product lines and invoice discount are consistent,
-- so total_amount = court_fee + product_fee - discount_amount for every row.
ON CONFLICT (id) DO UPDATE SET booking_id=EXCLUDED.booking_id, court_fee=EXCLUDED.court_fee, product_fee=EXCLUDED.product_fee, discount_amount=EXCLUDED.discount_amount, total_amount=EXCLUDED.total_amount, updated_at=CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET quantity=EXCLUDED.quantity, unit_price=EXCLUDED.unit_price, discount_amount=EXCLUDED.discount_amount, discount_percent=EXCLUDED.discount_percent;

COMMIT;

-- Expected report for 2026:
-- Court fee by quarter: Q1 = 240.000; Q2 = 240.000; Q3 = 300.000; Q4 = 120.000; total = 900.000.
-- Invoice total by quarter: Q1 = 540.000; Q2 = 655.000; Q3 = 545.000; Q4 = 410.000; total = 2.150.000.
-- Product total = invoice total - court fee, so the three totals reconcile for every quarter.
